				type: 'references',
				html: '\r\n          <h4>References:</h4>\r\n          <LanguageSets>\r\n            <div class="lang-set"><strong>Hebrew</strong>\r\n            <em>תַּחְמָס</em> \r\n            [tachmas] \r\n            <div class="ref-list">\r\n              <span class="ref-link" data-usfm="LEV 11:16_{00018}" title="LEV 11:16_{00018}">00301101600018</span>\r\n              <span class="ref-link" data-usfm="DEU 14:15_{00018}" title="DEU 14:15_{00018}">00501401500018</span>\r\n            </div>\r\n            </div>\r\n          </LanguageSets>\r\n          <Paragraphs />\r\n        '
