				type: 'references',
				html: '\r\n          <h4>References:</h4>\r\n          <LanguageSets>\r\n            <div class="lang-set"><strong>Hebrew</strong>\r\n            <em>תִּנְשֶׁמֶת</em> \r\n            [tinshemeth] \r\n            <div class="ref-list">\r\n              <span class="ref-link" data-usfm="LEV 11:18_{00008}" title="LEV 11:18_{00008}">00301101800008</span>\r\n              <span class="ref-link" data-usfm="DEU 14:16_{00020}" title="DEU 14:16_{00020}">00501401600020</span>\r\n            </div>\r\n            </div>\r\n          </LanguageSets>\r\n          <Paragraphs />\r\n        '
