				type: 'references',
				html: '\r\n          <h4>References:</h4>\r\n          <LanguageSets>\r\n            <div class="lang-set"><strong>Hebrew</strong>\r\n            <em>שַׁחַף</em> \r\n            [shachaf] \r\n            <div class="ref-list">\r\n              <span class="ref-link" data-usfm="LEV 11:16_{00026}" title="LEV 11:16_{00026}">00301101600026</span>\r\n              <span class="ref-link" data-usfm="DEU 14:15_{00026}" title="DEU 14:15_{00026}">00501401500026</span>\r\n            </div>\r\n            </div>\r\n          </LanguageSets>\r\n          <Paragraphs />\r\n        '
