				type: 'references',
				html: '\r\n        <h4>References:</h4>\r\n        <LanguageSets>\r\n          <div class="lang-set"><strong>Hebrew</strong>\r\n            <em>מִגְדָּל</em> \r\n            [migdal] \r\n            <div class="ref-list">\r\n              <Reference>H00101100400016</Reference>\r\n              <Reference>H00101100500024</Reference>\r\n            </div>\r\n          </div>\r\n        </LanguageSets>\r\n      '
